-- ============================================================
-- Lesson enhancements for "api-testing-masterclass" Module 4.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/api-module4.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
-- ============================================================

update public.lessons l set enhancements = $ench${"industryStory":"I inherited a project with 60 loose requests dumped into one collection, half named \"Copy of Login\". Nobody could find anything, so people rebuilt requests from scratch daily. We spent an afternoon folder-ing it by resource and renaming everything — the team's API work got visibly faster the next week.","visualAid":{"type":"comparison","title":"Messy vs organised collection","headers":["Aspect","Messy","Organised"],"rows":[["Structure","One flat list","Folders per resource"],["Names","New Request (3)","GET Single user"],["Auth","Pasted per request","Set once at collection level"],["Reusable","Rarely re-run","Run whole collection in one click"]]},"davidTip":"I name requests in the format `METHOD what-it-does` — `POST Create order — happy path`. When you can read a collection top to bottom and understand the API, you've built something a team will actually use.","miniChallenge":"Take five loose requests and reorganise them into at least two named folders that mirror the API's resources.","modelAnswer":"## Example\nCollection `Shop API` → folder `Products` (`GET List products`, `GET Single product`, `POST Create product`) and folder `Orders` (`POST Create order`, `GET Order status`). Auth set once at the collection level.","badGood":{"label":"request naming","bad":"Sidebar shows `New Request`, `New Request (2)`, `Copy of New Request` — nobody can tell them apart.","good":"Sidebar shows `GET List users`, `GET Single user`, `POST Create user` — the intent is obvious at a glance."},"resourcePreview":{"name":"Collection Structure Template","purpose":"A ready-made folder layout for a typical REST API.","whenToUse":"Import it when you start a new collection.","formats":["JSON"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 4 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A tester once ran a \"cleanup\" collection against production because the requests had prod URLs hardcoded and she forgot which tab was which. It deleted real records. After that we mandated `{{baseUrl}}` everywhere and made the environment dropdown the single thing you check before hitting Send.","visualAid":{"type":"timeline","title":"Variable resolution order","steps":[{"label":"Local / data","detail":"narrowest — from a data file or script"},{"label":"Environment","detail":"Dev / Staging / Prod values"},{"label":"Collection","detail":"shared defaults"},{"label":"Global","detail":"widest — across all collections"}]},"davidTip":"The first thing I do on any new collection is create `{{baseUrl}}` and `Dev`/`Staging` environments. It takes two minutes and it's the single change that turns a toy into a reusable suite.","miniChallenge":"Create a second environment (`Staging`) by duplicating `Dev`, give it a different `baseUrl`, and switch between them without editing any request.","modelAnswer":"## Example\n`Dev`: `baseUrl = https://reqres.in/api`. `Staging`: `baseUrl = https://staging.reqres.in/api`. Request URL: `{{baseUrl}}/users/{{userId}}`. Flipping the dropdown re-points all requests with zero edits.","badGood":{"label":"hardcoded vs variables","bad":"`GET https://staging.api.com/users/2` — the host and id are baked in; changing environment means editing every request.","good":"`GET {{baseUrl}}/users/{{userId}}` — switch the environment dropdown and everything re-points automatically."}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 4 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A regression suite of 200 requests was \"all green\" for months — then we noticed every single test only checked `status 200`. The API had been returning 200 with an empty body for one endpoint the whole time. We added body assertions and immediately found three more silent failures.","visualAid":{"type":"comparison","title":"Common pm assertions","headers":["Check","Assertion"],"rows":[["Status code","pm.response.to.have.status(201)"],["Body value","pm.expect(body.email).to.eql('eve@reqres.in')"],["Property exists","pm.expect(body).to.have.property('token')"],["Is an array","pm.expect(body.data).to.be.an('array')"],["Response time","pm.expect(pm.response.responseTime).to.be.below(800)"]]},"davidTip":"I parse the body once into a `const body` at the top of the script, then write lots of tiny named tests against it. Small assertions fail loudly and precisely — big ones just tell you \"something's wrong\".","miniChallenge":"Write a test that asserts the response is a JSON array and that it contains at least one item.","modelAnswer":"## Example\n```\nconst body = pm.response.json();\npm.test('data is a non-empty array', () => {\n  pm.expect(body.data).to.be.an('array');\n  pm.expect(body.data.length).to.be.above(0);\n});\n```","badGood":{"label":"test coverage","bad":"`pm.test('works', () => pm.response.to.have.status(200));` — vague name, only checks status.","good":"Separate named tests for status, each key body field and response time, so a failure points straight at the cause."}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 4 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A contractor hardcoded a bearer token into 40 requests. It expired every hour, so every morning the whole suite went red and someone re-pasted the token 40 times. We replaced it with a login request that captured the token into `{{token}}` once — the daily ritual disappeared overnight.","visualAid":{"type":"timeline","title":"Login → use-token chain","steps":[{"label":"Pre-request","detail":"prepare any setup data"},{"label":"POST /login","detail":"send credentials"},{"label":"Capture","detail":"pm.environment.set('token', body.token)"},{"label":"GET (protected)","detail":"header uses {{token}}"},{"label":"Assert","detail":"confirm 200 + expected body"}]},"davidTip":"Capturing the token once and referencing `{{token}}` everywhere is the single most useful Postman trick I teach. It turns a brittle demo into a suite that survives token expiry and re-runs cleanly.","miniChallenge":"Add a pre-request script that generates a unique email with `Date.now()` and use `{{email}}` in a create-user request body.","modelAnswer":"## Example\nPre-request: `pm.environment.set('email', \\`user_${Date.now()}@test.com\\`);` Body: `{\"name\":\"Sam\",\"email\":\"{{email}}\"}`. Each run sends a fresh, unique email, so the create never collides.","badGood":{"label":"auth handling","bad":"A bearer token pasted into every request's header — expires hourly and must be replaced by hand everywhere.","good":"A `POST /login` captures the token into `{{token}}`; every other request sends `Authorization: Bearer {{token}}`."}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 4 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"We needed to prove a validation endpoint rejected 30 malformed postcodes. Someone was about to build 30 requests by hand. Instead we made a 30-row CSV and one request — the whole matrix ran in seconds, and the failing-row report found two postcodes the dev had wrongly accepted.","visualAid":{"type":"timeline","title":"A data-driven run","steps":[{"label":"Data file","detail":"CSV/JSON, one row per case"},{"label":"Open Runner","detail":"select collection + environment"},{"label":"Attach data","detail":"columns become {{variables}}"},{"label":"Run","detail":"one iteration per row"},{"label":"Read results","detail":"per-iteration pass/fail"}]},"davidTip":"Add an `expectedStatus` (or `expectedError`) column to your data file and assert against `pm.iterationData.get(...)`. One request then covers happy path, boundaries and invalid input in a single run.","miniChallenge":"Add a fourth row to your CSV for an empty email, give it `expectedStatus 400`, and confirm the Runner asserts it correctly.","modelAnswer":"## Example\nCSV rows: valid (200), wrong password (400), missing password (400), empty email (400). The request asserts `pm.iterationData.get('expectedStatus')`, so all four cases pass or fail on their own terms in one run.","badGood":{"label":"testing many inputs","bad":"Thirty near-identical requests, each with a different email pasted in — impossible to maintain.","good":"One request plus a thirty-row CSV; the Runner iterates and reports pass/fail per row."},"resourcePreview":{"name":"Data-Driven Test CSV Pack","purpose":"Sample CSVs for valid, boundary and invalid cases.","whenToUse":"Attach one when practising the Collection Runner.","formats":["CSV","JSON"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 4 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"On one project the API was three weeks behind the UI. We took the agreed OpenAPI contract, saved example responses in Postman, and stood up a mock. The frontend and our test suite both built against it. When the real API shipped, we changed one variable — `baseUrl` — and 90% of the tests passed on the first run.","visualAid":{"type":"timeline","title":"Mock-first workflow","steps":[{"label":"Agree contract","detail":"endpoints, status, body shape"},{"label":"Save examples","detail":"attach example responses to requests"},{"label":"Create mock","detail":"Postman hosts a mock URL"},{"label":"Point baseUrl","detail":"run tests against the mock"},{"label":"Swap to real API","detail":"repoint baseUrl when backend lands"}]},"davidTip":"Mock-first is my favourite way to shift left. You turn \"we can't test yet, the API isn't ready\" into \"our tests are done and waiting\". When the backend arrives you're validating, not starting.","miniChallenge":"Save a second example on the same request with a `404` status and body, then work out how Postman decides which example the mock returns.","modelAnswer":"## Example\nRequest `GET /users/2` has two examples: a `200` with a user body and a `404` with `{\"error\":\"Not found\"}`. Postman matches on method, path and query/response-code hints; you can also force one with the `x-mock-response-code` header. The mock replays whichever example matches.","badGood":{"label":"testing before the API exists","bad":"\"We can't test yet — the backend isn't built.\" Testing starts late and gets squeezed at the end.","good":"Build a mock from the agreed contract, write tests against it, then repoint `{{baseUrl}}` when the real API lands."},"managersReview":{"intro":"If I reviewed your Module 4 Postman work as a lead, I'd look for:","strengths":["A tidy collection with folders and clear names","Environments and `{{variables}}` instead of hardcoded values","Named `pm.test` assertions on status and body","A working request chain and a data-driven run"],"improvements":["Cover invalid and boundary cases, not just happy paths","Add descriptions so the docs are genuinely useful","Use secret variable types for any credentials"],"gaps":["No assertions beyond status codes","Everything in one flat, unnamed collection","Tokens or URLs hardcoded across many requests"]},"portfolioBuilder":"Polish your `API Masterclass — <your name>` collection: folders per resource, `{{baseUrl}}` with Dev/Staging environments, `pm.test` assertions on each request, one login→token chain, one data-driven run, and published documentation. Export the JSON — this is a strong Module 10 portfolio artefact and something you can show in an interview.","resourcePreview":{"name":"Postman Mock & Docs Guide","purpose":"Step-by-step for creating mocks and publishing collection docs.","whenToUse":"Follow it when a backend is behind and you need to test early.","formats":["PDF"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 4 and l.lesson_number = 6;

